('1a000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','public-viewer-a@example.com','',now(),'{}','{}',now(),now()),
('1a000000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','public-owner-b@example.com','',now(),'{}','{}',now(),now());
insert into organizations(id,name,slug,phone,email,public_page_enabled,public_description) values('2a000000-0000-4000-8000-000000000001','Public Shop A','public-shop-a','09171234567','shop@example.com',true,'Public description'),('2a000000-0000-4000-8000-000000000002','Private Shop B','private-shop-b','09999999999','private@example.com',false,'Hidden');
insert into organization_memberships(organization_id,user_id,role) values('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','owner'),('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000002','advisor'),('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000003','viewer'),('2a000000-0000-4000-8000-000000000002','1a000000-0000-4000-8000-000000000004','owner');
insert into branches(id,organization_id,name,phone,email,address_line,city,province,timezone,is_primary,opening_hours) values('4a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','Public Main','09170000000','branch@example.com','1 Main St','Calamba','Laguna','Asia/Manila',true,'{"monday":{"open":"00:00","close":"23:59"},"tuesday":{"open":"00:00","close":"23:59"},"wednesday":{"open":"00:00","close":"23:59"},"thursday":{"open":"00:00","close":"23:59"},"friday":{"open":"00:00","close":"23:59"},"saturday":{"open":"00:00","close":"23:59"},"sunday":{"open":"00:00","close":"23:59"}}'),('4a000000-0000-4000-8000-000000000002','2a000000-0000-4000-8000-000000000002','Private Main','09990000000','hidden@example.com','Secret','Secret','Secret','Asia/Manila',true,'{}');
insert into service_categories(id,organization_id,name) values('7a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','Wash');
insert into services(id,organization_id,category_id,name,description,duration_minutes,base_price_centavos,is_public) values('8a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','7a000000-0000-4000-8000-000000000001','Public Wash','Safe description',60,50000,true),('8a000000-0000-4000-8000-000000000003','2a000000-0000-4000-8000-000000000001','7a000000-0000-4000-8000-000000000001','Internal Secret Service','Do not show',60,999999,false);
insert into shop_gallery_images(organization_id,url,alt_text) values('2a000000-0000-4000-8000-000000000001','https://example.com/shop.jpg','Clean shop bay');
