insert into vehicles(id,organization_id,customer_id,make,model,plate_number,plate_normalized) values('6a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001','Toyota','Vios','SECRET1','SECRET1');
create temporary table booking_tokens(kind text primary key,result jsonb);grant all on booking_tokens to anon,authenticated;

select plan(42);
select has_function('public','get_public_shop',array['text'],'curated shop RPC exists');select has_function('public','submit_public_booking',array['text','uuid','uuid[]','timestamp with time zone','text','text','text','text','text','integer','text','text','text','text','text'],'public booking RPC exists');select has_table('public','public_booking_requests','isolated requests table exists');select has_table('public','public_booking_rate_limits','rate limiter exists');
set local role anon;set local "request.jwt.claims"='{"role":"anon"}';
select throws_ok($$select * from organizations$$,'42501',null,'anon cannot read organizations');select throws_ok($$select * from branches$$,'42501',null,'anon cannot read branches');select throws_ok($$select * from services$$,'42501',null,'anon cannot read services');select throws_ok($$select * from customers$$,'42501',null,'anon cannot read customers');select throws_ok($$select * from vehicles$$,'42501',null,'anon cannot read vehicles');select throws_ok($$select * from appointments$$,'42501',null,'anon cannot read appointments');select throws_ok($$select * from payments$$,'42501',null,'anon cannot read payments');select throws_ok($$select * from public_booking_requests$$,'42501',null,'anon cannot read booking PII');
select is((get_public_shop('public-shop-a')->>'name'),'Public Shop A','published shop is public');select is(get_public_shop('private-shop-b'),null,'unpublished shop stays private');select is(jsonb_array_length(get_public_shop('public-shop-a')->'services'),1,'only explicitly public services returned');select ok(get_public_shop('public-shop-a')::text not like '%Existing Secret Customer%' and get_public_shop('public-shop-a')::text not like '%PRIVATE CRM NOTE%' and get_public_shop('public-shop-a')::text not like '%Internal Secret Service%','public shop payload contains no CRM or private service data');select is(jsonb_array_length(get_public_shop('public-shop-a')->'gallery'),1,'public gallery returned');
select ok((select count(*)>0 from get_public_availability('public-shop-a','4a000000-0000-4000-8000-000000000001','8a000000-0000-4000-8000-000000000001',current_date+2)),'availability exposes safe open slots');select is((select count(*) from get_public_availability('private-shop-b','4a000000-0000-4000-8000-000000000002','8a000000-0000-4000-8000-000000000001',current_date+2))::bigint,0::bigint,'unpublished shop has no availability');
insert into booking_tokens select 'valid',submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '2 days','Public Visitor','09171112222','visitor@example.com','Toyota','Fortuner',2024,'SUV','ABC123','Please confirm','rate-valid','');
select ok((select length(result->>'token')=64 from booking_tokens where kind='valid'),'booking returns random confirmation token');select ok((select result ? 'reference' and result ? 'token' and (select count(*) from jsonb_object_keys(result))=2 from booking_tokens where kind='valid'),'submission response exposes only reference and token');select throws_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '2 days','Public Visitor','09171112222','visitor@example.com','Toyota','Fortuner',2024,'SUV','ABC123','duplicate','rate-other','')$$,'P0001','A similar booking request is already pending','duplicate booking blocked');select throws_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '3 days','Bot User','09170000001',null,'Honda','City',2020,'Sedan',null,null,'rate-bot','filled')$$,'P0001','Unable to submit booking','honeypot blocks bots');select throws_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000003'::uuid],now()+interval '3 days','Private Service','09170000002',null,'Honda','City',2020,'Sedan',null,null,'rate-private','')$$,'P0001','Service unavailable','private service cannot be booked');
select ok((get_public_booking_status((select result->>'token' from booking_tokens where kind='valid')) ?& array['reference','status','shopName','branchName','preferredAt','services','declineReason']),'token status exposes documented fields');select ok(get_public_booking_status((select result->>'token' from booking_tokens where kind='valid'))::text not like '%09171112222%' and get_public_booking_status((select result->>'token' from booking_tokens where kind='valid'))::text not like '%ABC123%','status never exposes contact or vehicle identifiers');select is(get_public_booking_status(repeat('0',64)),null,'invalid token reveals nothing');
select lives_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '4 days','Rate One','09170000101',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'rate request one');select lives_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '5 days','Rate Two','09170000102',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'rate request two');select lives_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '6 days','Rate Three','09170000103',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'rate request three');select lives_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '7 days','Rate Four','09170000104',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'rate request four');select lives_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '8 days','Rate Five','09170000105',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'rate request five');select throws_ok($$select submit_public_booking('public-shop-a','4a000000-0000-4000-8000-000000000001',array['8a000000-0000-4000-8000-000000000001'::uuid],now()+interval '9 days','Rate Six','09170000106',null,'Honda','City',2020,'Sedan',null,null,'rate-limit','')$$,'P0001','Too many booking requests','sixth request in window is rate limited');
set local role authenticated;set local "request.jwt.claims"='{"sub":"1a000000-0000-4000-8000-000000000004","role":"authenticated"}';select is((select count(*) from public_booking_requests)::bigint,0::bigint,'Org B cannot read Org A booking requests');select throws_ok($$select review_public_booking((select id from public_booking_requests limit 1),'confirm',null)$$,'42501','Booking request not found','Org B cannot review Org A booking');
set local "request.jwt.claims"='{"sub":"1a000000-0000-4000-8000-000000000003","role":"authenticated"}';select throws_ok($$select review_public_booking((select id from public_booking_requests where public_reference=(select result->>'reference' from booking_tokens where kind='valid')),'confirm',null)$$,'42501','Booking request not found','viewer cannot review booking');
set local "request.jwt.claims"='{"sub":"1a000000-0000-4000-8000-000000000002","role":"authenticated"}';select lives_ok($$select review_public_booking((select id from public_booking_requests where public_reference=(select result->>'reference' from booking_tokens where kind='valid')),'confirm',null)$$,'advisor confirms booking');select is((select status::text from public_booking_requests where public_reference=(select result->>'reference' from booking_tokens where kind='valid')),'confirmed','booking marked confirmed');select is((select count(*) from appointments where source='public_booking')::bigint,1::bigint,'confirmed request creates one appointment');select is((select count(*) from appointment_services where appointment_id=(select appointment_id from public_booking_requests where public_reference=(select result->>'reference' from booking_tokens where kind='valid')))::bigint,1::bigint,'service snapshot copied to appointment');select is((select count(*) from customers where email='visitor@example.com')::bigint,1::bigint,'customer matched or created internally once');select throws_ok($$select review_public_booking((select id from public_booking_requests where public_reference=(select result->>'reference' from booking_tokens where kind='valid')),'confirm',null)$$,'P0001','Invalid booking transition','confirmed request cannot replay');
select * from finish();rollback;
